    private static byte[] bytes(String text) { return text.getBytes(StandardCharsets.UTF_8); }
    private static void check(boolean valid,String reason) { if (!valid) throw new AssertionError("ZIP export: "+reason); }
    @FunctionalInterface private interface Action { void run() throws Exception; }
    private static void rejects(Action action) throws Exception { try { action.run(); } catch (IOException | IllegalArgumentException | IllegalStateException | NullPointerException expected) { return; }throw new AssertionError("Expected rejected export"); }
    private static void cancelled(Action action) throws Exception { try { action.run(); } catch (CancellationException expected) { return; }throw new AssertionError("Expected cancelled export"); }
    private static PackWorkspace pack() throws Exception { return PackWorkspace.newPack(Map.of(JSON,bytes("{\r\n \"block\":\"minecraft:stone\",\"future\":9007199254740993,\"text\":\"雪\\u0061\"\r\n}"),BINARY,new byte[]{0,-1,4,9},"future/malformed.json",bytes("unknown bad JSON\r\n"),"zero.raw",new byte[0])); }
    private static String hash(Path path) throws Exception { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path))); }
    private static ZipExports.Receipt export(ZipExportSource source,Path path,boolean replace) throws Exception { return ZipExports.export(source,path,replace,new ZipExports.Control(),(entries,bytes) -> {}); }
    private static void noTemporary(Path folder) throws Exception { try (var paths=Files.list(folder)) { check(paths.noneMatch(p -> p.getFileName().toString().startsWith(".iris-export-")),"temporary archives removed after completion/failure/cancellation"); } }
